select ra.role_id, ia.industry_code, ia.app_ver_code from sys_industry_auth ia inner join sys_role_industry_auth ra on ia.auth_id = ra.auth_id where ia.industry_code in
#{item}
and ia.app_ver_code in
#{item}
and (ia.tenant_id is null or ia.tenant_id = '') and (ra.tenant_id is null or ra.tenant_id = '') group by ia.industry_code, ia.app_ver_code, ra.role_id

select distinct role_id
from sys_user_role
where user_id  = #{userId}
